"""Account and catalog screens."""

TEMPLATES = {
    'login.html': '''{% extends 'base.html' %}{% block body %}<h1>Вход сотрудника</h1><p class="intro muted">Аккаунт создаётся по приглашению координатора.</p>{% if error %}<div class="notice error" role="alert">{{ error }}</div>{% endif %}<form method="post" class="panel form-panel" style="max-width:500px;margin-top:24px"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="field"><label for="username">Логин</label><input id="username" name="username" autocomplete="username" maxlength="32" required value="{{ username }}"></div><div class="field"><label for="password">Пароль</label><input id="password" type="password" name="password" autocomplete="current-password" maxlength="128" required></div><button>Войти</button></form>{% endblock %}''',

    'join.html': '''{% extends 'base.html' %}{% block body %}<h1>Создание аккаунта</h1><p class="intro muted">Ваша роль: <strong>{{ roles[invitation.role] }}</strong>. Приглашение действует один раз.</p>{% if error %}<div class="notice error" role="alert">{{ error }}</div>{% endif %}<form method="post" class="panel form-panel" style="max-width:550px;margin-top:24px"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="field"><label for="username">Логин</label><input id="username" name="username" autocomplete="username" minlength="3" maxlength="32" value="{{ username }}" required aria-describedby="username-help"><p class="help" id="username-help">3–32 русские или латинские буквы, цифры, точка, дефис или подчёркивание. Без пробелов. Например: Андрей33 или Rey33.</p></div><div class="field"><label for="password">Пароль</label><input id="password" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required aria-describedby="password-help"><p class="help" id="password-help">От 12 до 128 символов. Можно использовать длинную фразу.</p></div><div class="field"><label for="password-repeat">Повторите пароль</label><input id="password-repeat" type="password" name="password_repeat" autocomplete="new-password" minlength="12" maxlength="128" required></div><button>Создать аккаунт</button></form>{% endblock %}''',

    'accounts.html': '''{% extends 'base.html' %}{% block body %}<h1>Сотрудники</h1><p class="intro muted">Сотрудники получают доступ по одноразовым приглашениям. Срок ссылки — 24 часа.</p>{% if error %}<div class="notice error" role="alert">{{ error }}</div>{% endif %}{% if invitation_url %}<section class="panel" style="margin-top:24px"><h2>Приглашение создано</h2><label for="invite">Ссылка для сотрудника</label><input id="invite" readonly value="{{ invitation_url }}"><p class="help">Скопируйте и передайте адрес лично. Ссылка предоставляет выбранную роль. После ухода со страницы она больше не показывается.</p></section>{% endif %}<div class="grid2" style="margin-top:24px"><section class="panel"><h2>Аккаунты</h2><table><thead><tr><th scope="col">Логин</th><th scope="col">Роль</th></tr></thead><tbody>{% for u in users %}<tr><td>{{ u.username }}</td><td>{{ roles[u.role] }}</td></tr>{% endfor %}</tbody></table></section><section class="panel"><h2>Пригласить сотрудника</h2><form method="post"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="field"><label for="role">Роль</label><select id="role" name="role">{% for key,label in roles.items() %}<option value="{{ key }}" {% if key=='observer' %}selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><button>Создать приглашение</button></form><p class="help">Координатор: заявки, резервы, справочники и сотрудники.<br>Сотрудник склада: поступления и передача.<br>Наблюдатель: только просмотр.</p></section></div>{% endblock %}''',

    'catalogs.html': '''{% extends 'base.html' %}{% block body %}<h1>Справочники</h1><p class="intro muted">Загрузка складов и товаров из CSV. Импорт не создаёт поступлений и не меняет остатки.</p>{% if error %}<div class="notice error" role="alert">{{ error }}</div>{% endif %}<section class="panel" style="margin-top:24px"><h2>Импорт CSV</h2><div class="actions"><a href="{{ url_for('catalog_template',kind='products') }}">Шаблон товаров</a><a href="{{ url_for('catalog_template',kind='warehouses') }}">Шаблон складов</a></div><p class="help" id="csv-help">UTF-8, разделитель «;», до 50 КБ и 200 строк. Сначала проверяется весь файл. Ошибка отменяет импорт целиком. Существующие названия с той же единицей пропускаются.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="{{ csrf }}"><div class="form-grid"><div class="field"><label for="kind">Справочник</label><select id="kind" name="kind"><option value="products">Товары</option><option value="warehouses">Склады</option></select></div><div class="field"><label for="file">CSV-файл</label><input id="file" type="file" name="file" accept=".csv,text/csv" required aria-describedby="csv-help"></div></div><button>Проверить и импортировать</button></form></section><div class="grid2"><section class="panel"><h2>Товары</h2><table><thead><tr><th scope="col">Наименование</th><th scope="col">Единица</th></tr></thead><tbody>{% for p in products %}<tr><td>{{ p.name }}</td><td>{{ p.unit }}</td></tr>{% else %}<tr><td colspan="2">Товаров пока нет.</td></tr>{% endfor %}</tbody></table></section><section class="panel"><h2>Склады</h2>{% for w in warehouses %}<p>{{ w.name }}</p>{% else %}<p>Складов пока нет.</p>{% endfor %}</section></div>{% endblock %}''',
}
